import { mkdir, readFile, writeFile, cp, rm } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { copy } from '../src/i18n.mjs';
import { advertisingContact, advertisingCopy, advertisingUpdated } from '../src/advertising.mjs';
import { legalCopy, legalUpdated, legalContact, privacyReferences } from '../src/legal.mjs';
import { latestRelease, releaseDataFor, releaseCopyFor, renderLatestRelease, renderLatestCommit, renderReleaseList, renderReleaseSnapshot } from '../src/releases.mjs';
import { gettingStarted, gettingStartedReviewed } from '../src/getting-started.mjs';
import { bananaCompatibility } from '../src/banana-compatibility.mjs';
import { platforms, platformCopy, platformsReviewed } from '../src/platforms.mjs';
import { emulators, games, genres, languages, languageNames, reviewed } from '../src/data.mjs';
import { tools, toolCopy, toolsReviewed } from '../src/tools.mjs';
const root = fileURLToPath(new URL('../', import.meta.url));
export const siteURL = new URL(process.env.SITE_URL || 'https://switch2e.com').origin;
const out = resolve(root, 'dist');
await rm(out, { recursive: true, force: true });
await mkdir(out, { recursive: true });
await cp(resolve(root, 'public'), out, { recursive: true });
const emulatorIcons = JSON.parse(await readFile(resolve(root, 'src/cache/icons.json'), 'utf8'));
let cache = {}, media = {};
try { cache = JSON.parse(await readFile(resolve(root, 'src/cache/releases.json'), 'utf8')); } catch {}
try { media = JSON.parse(await readFile(resolve(root, 'src/cache/media.json'), 'utf8')); } catch {}
for (const tool of tools) cache[tool.id] = releaseDataFor(tool, cache[tool.id]);
export const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const json = x => JSON.stringify(x).replaceAll('<', '\\u003c');
// English uses the root path; localized pages retain their language prefix.
const href = (l, p = '') => l === 'en' ? `/${p ? `${p}/` : ''}` : `/${l}/${p ? `${p}/` : ''}`;
const absolute = p => `${siteURL}${p}`;
const clipDescription = (text, l) => {
  const chars = [...text];
  const limit = l === 'en' ? 155 : 100;
  if (chars.length <= limit) return text;
  let excerpt = chars.slice(0, limit - 1).join('');
  // Keep English words intact when using a longer introduction as the fallback.
  if (l === 'en' && !/\s/u.test(chars[limit - 1])) excerpt = excerpt.replace(/\s+\S*$/u, '');
  return `${excerpt.replace(/[\s,;:，、；：-]+$/u, '')}…`;
};
const external = (url, text, cls = '') => `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text}<span aria-hidden="true"> ↗</span></a>`;
const icon = name => ({ arrow: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>', search: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg>', download: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M5 16v4h14v-4"/></svg>' }[name]);
const mark = '<span class="brand-mark" aria-hidden="true"><i></i><i></i></span>';
const staticNotice = l => `<aside class="static-notice" aria-label="${l === 'en' ? 'Static demo' : l === 'ja' ? '静的デモ' : '静态演示'}"><p>${{
  en: 'Open-source static demo. Release data is a bundled snapshot; advertising, terms and privacy pages are examples from the original site.',
  'zh-CN': '开源静态演示：版本数据为随代码附带的快照；广告、条款与隐私页为原站内容示例。',
  ja: 'オープンソースの静的デモ。リリースは同梱のスナップショットです。広告・規約・プライバシーページは元サイトの例です。'
}[l]} <a href="https://switch2e.com${l === 'en' ? '/' : `/${l}/`}" target="_blank" rel="noopener noreferrer">${l === 'en' ? 'Visit Switch2e' : l === 'ja' ? 'Switch2e を開く' : '访问线上 Switch2e'} ↗</a></p></aside>`;

function art(g, eager = false) { return media[g.id] ? `<img src="/assets/games/${g.id}.webp" alt="${esc(g.name)}" width="720" height="405" loading="${eager ? 'eager' : 'lazy'}" decoding="async">` : `<div class="art-fallback ${g.color}"><span>SWITCH 2</span><strong>${esc(g.name)}</strong></div>`; }
const emuIcon = (e,small=false) => `<span class="emu-icon ${e.color}${small?' emu-icon-small':''}${emulatorIcons[e.id]?' has-image':''}" aria-hidden="true">${emulatorIcons[e.id]?`<img src="${emulatorIcons[e.id].file}" alt="" width="192" height="192" decoding="async">`:e.symbol}</span>`;
function emuCard(e, l, showGames = false) { const t = copy[l], latest = latestRelease(cache[e.id]), downloadHref = `${href(l, `emulators/${e.id}`)}#downloads`; return `<article class="emu-card" data-item data-kind="emulator" data-name="${esc(`${e.name} ${e.owner} ${e.alias || ''}`.toLowerCase())}" data-platforms="${e.platforms.join(',')}"><div class="card-top">${emuIcon(e)}<span class="status ${e.statusKey}"><i></i>${e.status[l]}</span></div><div class="card-owner">${esc(e.owner)} / ${e.kind === 'general' ? 'CORE' : e.kind === 'optimized' ? 'TUNED' : 'FORK'}</div><h3><a href="${href(l, `emulators/${e.id}`)}">${e.name}</a></h3><p>${e.summary[l]}</p><div class="card-release" data-release-id="${e.id}" data-release-href="${downloadHref}" ${latest || cache[e.id]?.fetchedAt ? '' : 'hidden'}>${renderLatestRelease(cache[e.id], t, downloadHref)}</div><div class="platforms">${e.platforms.map(p => `<span>${p}</span>`).join('')}</div>${showGames ? emulatorGameLinks(e,l) : ''}<div class="card-bottom"><span>${e.label[l]}</span><a href="${href(l, `emulators/${e.id}`)}" aria-label="${t.details}: ${esc(e.name)}">${icon('arrow')}</a></div></article>`; }
function emulatorGameLinks(e,l) {
 const entries=games.filter(g=>g.recommendations.includes(e.id));
 if(!entries.length)return '';
 return `<div class="emu-games"><span>${copy[l].recommendedGames}</span><ul>${entries.map(g=>`<li><a href="${href(l,`games/${g.id}`)}" aria-label="${esc(g.name)}"><img src="/assets/game-placeholder.svg" alt="" width="44" height="44" loading="lazy" decoding="async"><span class="game-icon-label" aria-hidden="true">${esc(g.name)}</span></a></li>`).join('')}</ul></div>`;
}
function gameCard(g, l) { const t = copy[l]; return `<article class="game-card" data-item data-kind="game" data-name="${esc(`${g.name} ${g.summary[l]}`.toLowerCase())}" data-genre="${g.genre}"><a class="game-art" href="${href(l, `games/${g.id}`)}" aria-label="${esc(g.name)}">${art(g)}<span class="game-year">SWITCH 2 · ${g.year}</span><span class="art-arrow" aria-hidden="true">↗</span></a><div class="game-body"><div class="game-meta"><span>${genres[g.genre][l]}</span><span class="evidence ${g.evidence}">${t[g.evidence]}</span></div><h3><a href="${href(l, `games/${g.id}`)}">${esc(g.name)}</a></h3><div class="game-projects"><span>${t.recommended}</span><div>${g.recommendations.map(id => { const e = emulators.find(x => x.id === id); return `<a href="${href(l, `emulators/${id}`)}">${emuIcon(e,true)} ${e.name} <span aria-hidden="true">↗</span></a>`; }).join('')}${tools.filter(e=>e.game===g.id).map(e=>`<a href="${href(l,`tools/${e.id}`)}">${e.name} · ${e.maintenance==='discontinued'?toolCopy.discontinued[l]:toolCopy.label[l]} ↗</a>`).join('')}</div></div></div></article>`; }
function faq(l) { const t = copy[l]; return `<section class="faq-section" id="faq"><div><p class="eyebrow">${t.section03}</p><h2>${t.faqTitle}</h2><p class="muted">${t.faqIntro}</p><a class="text-link" href="${href(l, 'about')}">${t.about} ↗</a></div><div class="faq-list">${t.faqs.map(([q,a]) => `<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section>`; }
function cta(l) { const t = copy[l]; return `<section class="cta"><div class="cta-spark" aria-hidden="true">✳</div><div><h2>${t.ctaTitle}</h2><p>${t.ctaText}</p></div><a class="button lime" href="${href(l, 'guide')}">${t.ctaButton}${icon('arrow')}</a></section>`; }
function sectionHead(num, title, desc, link, label, heading = 'h2') { return `<div class="section-head"><div>${num ? `<p class="eyebrow">${num}</p>` : ''}<${heading}>${title}</${heading}><p class="muted">${desc}</p></div>${link ? `<a class="text-link" href="${link}">${label} ${icon('arrow')}</a>` : ''}</div>`; }
function empty(t) { return `<div class="empty-state" hidden><span aria-hidden="true">⌕</span><h3>${t.empty}</h3><p>${t.emptyNote}</p><button class="button secondary" data-reset>${t.reset}</button></div>`; }
function emuSection(l, standalone = false, homepage = false) { const t = copy[l]; return `<section id="emulators" class="directory-section${homepage ? ' home-directory' : ''}" data-directory="emulator">${standalone ? '' : sectionHead(homepage ? '' : t.section01, homepage ? `Switch 2 ${t.emulators}` : t.emuHeading, t.emuIntro, homepage ? null : href(l,'emulators'), t.viewAll, homepage ? 'h1' : 'h2')}<div class="filter-bar"><div class="filter-chips" role="group" aria-label="${t.platforms}">${['all',...new Set(emulators.flatMap(e=>e.platforms))].map((p,i)=>`<button class="chip ${i===0?'active':''}" data-filter="${p}" aria-pressed="${i===0}">${p === 'all' ? t.all : p}</button>`).join('')}</div><span class="result-count" aria-live="polite">${emulators.length} ${t.projects}</span></div><div class="emu-grid">${emulators.map(e=>emuCard(e,l,homepage)).join('')}</div>${empty(t)}${platformLinks(l)}</section>`; }
function gameSection(l, standalone = false) { const t = copy[l]; return `<section id="games" class="directory-section" data-directory="game">${standalone ? '' : sectionHead(t.section02,t.gameHeading,t.gameIntro,href(l,'games'),t.viewAll)}<div class="filter-bar"><div class="filter-chips" role="group" aria-label="${t.genre}">${['all',...Object.keys(genres)].map((p,i)=>`<button class="chip ${i===0?'active':''}" data-genre-filter="${p}" aria-pressed="${i===0}">${p==='all'?t.allGames:genres[p][l]}</button>`).join('')}</div></div><div class="game-grid">${games.map(g=>gameCard(g,l)).join('')}</div>${empty(t)}</section>`; }
function platformLinks(l,current='') {return `<nav class="platform-links" aria-label="${platformCopy.label[l]}"><span>${platformCopy.label[l]}</span>${platforms.map(platform=>`<a href="${href(l,`platforms/${platform.id}`)}" ${current===platform.id?'aria-current="page"':''}>${platform.name}</a>`).join('')}</nav>`;}
function platformPage(platform,l) {
 const t=copy[l],entries=emulators.filter(e=>e.platforms.includes(platform.name));
 const sources=[...new Set(entries.flatMap(e=>gettingStarted[e.id].sources.map(source=>source.url)))];
 return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${href(l)}">${t.home}</a><span>/</span><a href="${href(l,'emulators')}">${t.emulators}</a><span>/</span><span aria-current="page">${platform.name}</span></nav><header class="listing-heading"><p class="eyebrow">SWITCH2E / ${platform.name}</p><h1>${esc(platform.title[l])}</h1><p class="detail-lede">${esc(platform.intro[l])}</p></header>${platformLinks(l,platform.id)}<section class="platform-directory" aria-labelledby="platform-projects"><h2 id="platform-projects">${platformCopy.projects[l]}</h2><p class="muted">${platformCopy.note[l]}</p><div class="emu-grid">${entries.map(e=>emuCard(e,l)).join('')}</div></section><section class="platform-guidance" aria-labelledby="platform-guidance"><h2 id="platform-guidance">${platformCopy.beforeDownload[l]}</h2><div class="editorial-grid">${platform.sections.map(section=>`<section class="editorial-card"><h3>${esc(section.title[l])}</h3><p>${esc(section.text[l])}</p></section>`).join('')}</div><a class="text-link" href="${href(l,'guide')}">${t.guide} ↗</a></section><section class="sources"><p class="eyebrow">${t.citations}</p><p>${t.setupReviewed} <time datetime="${platformsReviewed}">${platformsReviewed}</time></p><ul>${sources.map(url=>`<li>${external(url,esc(url.replace('https://','')))}</li>`).join('')}</ul></section>`;
}
function successorLink(e,l,cls='text-link') {
 const successor=tools.find(tool=>tool.id===e.successor);
 return successor?`<a class="${cls}" href="${href(l,`tools/${successor.id}`)}">${toolCopy.successor[l]} ${esc(successor.name)} <span aria-hidden="true">↗</span></a>`:'';
}
function retirementNotice(e,l) {
 if(!e.retirement)return '';
 return `<aside class="retirement-notice" aria-labelledby="retirement-heading"><span class="maintenance-badge">${toolCopy.discontinued[l]}</span><h2 id="retirement-heading">${toolCopy.retirementHeading[l]}</h2><p>${esc(e.retirement[l])}</p>${successorLink(e,l,'button primary')} <a class="text-link" href="${href(l,`tools/${e.successor}`)}#migration">${tools.find(tool=>tool.id===e.successor).sections.find(section=>section.id==='migration').title[l]} ↗</a></aside>`;
}
function toolCard(e,l) {
 const t=copy[l],game=games.find(g=>g.id===e.game),url=href(l,`tools/${e.id}`);
 return `<article class="tool-card"><a class="tool-card-art" href="${url}" aria-label="${esc(e.name)} — ${esc(game.name)}">${art(game)}</a><div class="tool-card-copy"><p class="card-owner">${esc(e.owner)} / STATIC RECOMPILATION</p>${e.maintenance==='discontinued'?`<span class="maintenance-badge">${toolCopy.discontinued[l]}</span>`:''}<h3><a href="${url}">${esc(e.name)}</a></h3><p class="tool-card-summary">${esc(e.summary[l])}</p><div class="platforms">${e.platforms.map(p=>`<span>${esc(p)}</span>`).join('')}</div><div class="card-release" data-release-id="${e.id}" data-release-href="${url}#downloads">${renderLatestRelease(cache[e.id],releaseCopyFor(e,t),`${url}#downloads`)}</div><div class="card-bottom">${successorLink(e,l)||`<a class="text-link" href="${url}">${t.details}${icon('arrow')}</a>`}</div></div></article>`;
}
function toolGrid(entries,l) {return `<div class="emu-grid tools-grid">${entries.map(e=>toolCard(e,l)).join('')}</div>`;}
function toolSection(l,standalone=false,entries=tools) {
 return `<section id="tools" class="directory-section tools-section">${sectionHead('',toolCopy.heading[l],toolCopy.intro[l],standalone?null:href(l,'tools'),copy[l].viewAll)}${toolGrid(entries,l)}</section>`;
}
function toolReferenceSections(e,l) {
 return (e.sections||[]).map(section=>`<section id="${section.id}" class="tool-reference" aria-labelledby="${section.id}-heading"><h2 id="${section.id}-heading">${esc(section.title[l])}</h2>${(section.paragraphs||[]).map(text=>`<p>${esc(text[l])}</p>`).join('')}${section.rows?`${section.columns.length>2?`<p class="table-scroll-hint">${l==='en'?'Swipe horizontally to compare all columns.':l==='ja'?'横にスクロールして全項目を比較できます。':'左右滑动表格可查看全部配置对比。'}</p>`:''}<div class="tool-table-scroll" role="region" aria-labelledby="${section.id}-heading" tabindex="0"><table class="tool-reference-table${section.columns.length>2?' comparison':''}"><caption>${esc(e.name)} — ${esc(section.title[l])}</caption><thead><tr>${section.columns.map(text=>`<th scope="col">${esc(text[l])}</th>`).join('')}</tr></thead><tbody>${section.rows.map(row=>`<tr>${row.map((text,i)=>`<${i===0?'th scope="row"':'td'}>${esc(text[l])}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${external(section.source,copy[l].sourceLink,'text-link')}</section>`).join('');
}
function toolPage(e,l) {
 const t=copy[l],game=games.find(g=>g.id===e.game),retired=e.maintenance==='discontinued';
 return `${breadcrumb(l,'tools',e.name)}${retirementNotice(e,l)}<section class="detail-hero"><div><p class="eyebrow">STATIC RECOMPILATION / ${esc(e.owner)}</p><h1>${esc(e.name)}</h1><p class="detail-lede">${esc(e.summary[l])}</p><div class="card-release detail-release" data-release-id="${e.id}" data-release-href="#downloads" ${latestRelease(cache[e.id]) || cache[e.id]?.fetchedAt ? '' : 'hidden'}>${renderLatestRelease(cache[e.id],releaseCopyFor(e,t),'#downloads')}</div><div class="hero-actions">${retired?successorLink(e,l,'button primary'):`<a class="button primary" href="#downloads">${icon('download')}${t.downloads}</a>`}<a class="button secondary" href="#getting-started">${retired?toolCopy.archivedGuide[l]:t.guide}</a>${retired?'':external(e.repo,t.sourceLink,'button secondary')}</div></div><aside class="fact-card"><p class="eyebrow">${t.quickFacts}</p><dl><div><dt>${t.maintainer}</dt><dd>${esc(e.owner)}</dd></div>${e.maintenance?`<div><dt>${t.status}</dt><dd>${retired?toolCopy.discontinued[l]:toolCopy.active[l]}</dd></div>`:''}<div><dt>${t.platforms}</dt><dd>${esc(e.platforms.join(' / '))}</dd></div><div><dt>${t.setupReviewed}</dt><dd><time datetime="${e.reviewed}">${e.reviewed}</time></dd></div><div><dt>${l==='en'?'License':l==='ja'?'ライセンス':'许可证'}</dt><dd>${e.license}</dd></div></dl></aside></section><div class="detail-columns"><div>${e.sections?`<nav class="tool-contents" aria-label="${t.overview}"><a href="#getting-started">${t.guide}</a><a href="#downloads">${t.downloads}</a>${e.sections.map(section=>`<a href="#${section.id}">${esc(section.title[l])}</a>`).join('')}</nav>`:''}<section class="prose tool-overview"><h2>${t.overview}</h2><p>${esc(e.detail[l])}</p><aside class="inline-note">${esc(e.note[l])}</aside><h2>${toolCopy.requirements[l]}</h2><ul class="tool-points">${e.requirements.map(text=>`<li>${esc(text[l])}</li>`).join('')}</ul><h2>${toolCopy.features[l]}</h2><ul class="tool-points">${e.features.map(text=>`<li>${esc(text[l])}</li>`).join('')}</ul></section><section id="getting-started" class="getting-started"><h2>${retired?toolCopy.archivedGuide[l]:t.guide}</h2><ol class="setup-steps">${e.steps.map(text=>`<li><p>${esc(text[l])}</p></li>`).join('')}</ol></section>${releaseList(e,l)}${toolReferenceSections(e,l)}<section class="tool-faq"><h2>${toolCopy.faq[l]}</h2><div class="faq-list">${e.faqs.map(item=>`<details><summary>${esc(item.question[l])}<span aria-hidden="true">+</span></summary><p>${esc(item.answer[l])}</p></details>`).join('')}</div></section></div><aside class="detail-sidebar"><p class="eyebrow">${t.relatedGames}</p><a class="mini-game" href="${href(l,`games/${game.id}`)}"><div>${art(game)}</div><span>${esc(game.name)} ↗</span></a><a class="text-link" href="${href(l,`games/${game.id}`)}">${toolCopy.gameLink[l]} ↗</a>${tools.filter(other=>other.game===e.game&&other.id!==e.id).map(other=>`<a class="text-link" href="${href(l,`tools/${other.id}`)}">${t.relatedProjects}: ${esc(other.name)} ↗</a>`).join('')}<a class="text-link" href="${href(l,'about')}">${t.about} ↗</a></aside></div><section class="sources"><p class="eyebrow">${t.citations}</p><p>${t.setupReviewed} <time datetime="${e.reviewed}">${e.reviewed}</time> · README <code>${e.sourceRevision.slice(0,7)}</code></p><ul>${e.sources.map(url=>`<li>${external(url,esc(url.replace('https://','')))}</li>`).join('')}</ul></section>`;
}
function advertisingTeaser(l) {
  const a = advertisingCopy[l];
  return `<aside class="advertising-teaser"><div><p class="eyebrow">SWITCH2E / ${esc(a.label)}</p><h2>${esc(a.teaserTitle)}</h2><p>${esc(a.teaserText)}</p></div><a class="button secondary" href="${href(l,'advertise')}">${esc(a.label)}${icon('arrow')}</a></aside>`;
}
function advertisingPage(l) {
  const a = advertisingCopy[l];
  return `${breadcrumb(l,'advertise')}<div class="advertising-hero"><header class="article-heading"><p class="eyebrow">SWITCH2E / ${esc(a.label)}</p><h1>${esc(a.title)}</h1><p class="detail-lede">${esc(a.intro)}</p><div class="advertising-topics">${a.topics.map(topic=>`<span>${esc(topic)}</span>`).join('')}</div></header><aside class="advertising-contact" aria-labelledby="advertising-contact-title"><p class="eyebrow">LET’S CONNECT / TELEGRAM</p><h2 id="advertising-contact-title">${esc(a.contactTitle)}</h2><p>${esc(a.contactText)}</p><a class="advertising-handle" href="${advertisingContact.url}" target="_blank" rel="noopener noreferrer">${advertisingContact.handle}<span aria-hidden="true"> ↗</span></a>${external(advertisingContact.url,esc(a.contactButton),'button lime')}<p class="advertising-contact-note">${esc(a.contactNote)}</p></aside></div><section class="advertising-audience" aria-labelledby="advertising-audience-title"><h2 id="advertising-audience-title">${esc(a.audience)}</h2><p>${esc(a.audienceText)}</p></section><section class="advertising-section" aria-labelledby="advertising-formats-title"><h2 id="advertising-formats-title">${esc(a.formatsTitle)}</h2><p class="muted">${esc(a.formatsIntro)}</p><div class="advertising-formats">${a.formats.map(([title,text],i)=>`<article class="editorial-card"><span class="step-number" aria-hidden="true">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}</div></section><section class="advertising-section" aria-labelledby="advertising-steps-title"><h2 id="advertising-steps-title">${esc(a.stepsTitle)}</h2><ol class="advertising-steps">${a.steps.map(([title,text])=>`<li><h3>${esc(title)}</h3><p>${esc(text)}</p></li>`).join('')}</ol></section><p class="inline-note advertising-note">${esc(a.note)}</p>`;
}
function home(l) { return `${emuSection(l, false, true)}${toolSection(l)}${gameSection(l)}${cta(l)}${faq(l)}${advertisingTeaser(l)}`; }
const breadcrumb = (l, type, name='') => {const t=copy[l]; return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${href(l)}">${t.home}</a><span>/</span>${name?`<a href="${href(l,type)}">${type==='tools'?toolCopy.label[l]:t[type]}</a><span>/</span><span aria-current="page">${esc(name)}</span>`:`<span aria-current="page">${type==='tools'?toolCopy.label[l]:t[type]||t.about}</span>`}</nav>`;};
function citations(l, sources, sourceReviewed=reviewed) { const t=copy[l]; return `<section class="sources"><p class="eyebrow">${t.citations}</p><p>${t.reviewText} <time datetime="${sourceReviewed}">${sourceReviewed}</time>.</p><ul>${[...new Set(sources)].map(url=>`<li>${external(url,esc(url.replace('https://','')))}</li>`).join('')}</ul></section>`; }
function gettingStartedSection(e,l) {
 const t=copy[l],guide=gettingStarted[e.id],setupReviewed=guide.reviewed||gettingStartedReviewed;
 return `<section id="getting-started" class="getting-started" aria-labelledby="getting-started-heading"><p class="eyebrow">${esc(e.name)}</p><h2 id="getting-started-heading">${t.guide}</h2><p class="setup-note">${esc(guide.note[l])}</p><ol class="setup-steps">${guide.steps.map(step=>`<li><h3>${esc(step.title[l])}</h3><p>${esc(step.text[l])}</p></li>`).join('')}</ol><div class="setup-sources"><p>${t.setupSources} · ${t.setupReviewed} <time datetime="${setupReviewed}">${setupReviewed}</time></p><ul>${guide.sources.map(source=>`<li>${external(source.url,esc(source.label))}</li>`).join('')}</ul></div></section>`;
}
const compatibilityStatus = (row,t) => t[row.status==='supported'?'compatibilitySupported':row.status==='playable'?'compatibilityPlayable':'compatibilityExperimental'];
function bananaGameNote(g,l) {
 const row=bananaCompatibility.rows.find(row=>row.game===g.id),t=copy[l];
 return `<p class="compatibility-game-note">Banana Native (Android) — ${esc(compatibilityStatus(row,t))}. ${esc(row.notes[l])} ${t.compatibilityVersion}: ${esc(row.version)}.</p>`;
}
function reportedGameNote(e,g,l) {
 const row=e.compatibility?.rows.find(row=>row.game===g.id);
 return row?`<p class="compatibility-game-note">${esc(e.name)} (Android) — ${esc(row.notes[l])} ${external(e.compatibility.source,copy[l].sourceLink)}</p>`:'';
}
function compatibilitySection(e,l) {
 if(e.compatibility){
  const t=copy[l],report=e.compatibility;
  return `<section id="game-compatibility" class="compatibility-section" aria-labelledby="compatibility-heading"><h2 id="compatibility-heading">${t.compatibilityTitle}</h2><p class="muted">${esc(report.intro[l])}</p><div class="compatibility-scroll" role="region" aria-labelledby="compatibility-heading" tabindex="0"><table class="compatibility-table"><caption>${esc(e.name)} — ${t.reported}</caption><thead><tr><th scope="col">${t.compatibilityGame}</th><th scope="col">${t.compatibilityNotes}</th></tr></thead><tbody>${report.rows.map(row=>`<tr><th scope="row"><a href="${href(l,`games/${row.game}`)}">${esc(games.find(game=>game.id===row.game).name)}</a></th><td>${esc(row.notes[l])}</td></tr>`).join('')}</tbody></table></div><div class="setup-sources"><p>${t.reported} · ${t.setupReviewed} <time datetime="${report.reviewed}">${report.reviewed}</time></p><ul>${[report.source,report.releaseSource].map(source=>`<li>${external(source,t.sourceLink)}</li>`).join('')}</ul></div></section>`;
 }
 if(e.id!=='banana-native')return '';
 const t=copy[l];
 return `<section id="game-compatibility" class="compatibility-section" aria-labelledby="compatibility-heading"><h2 id="compatibility-heading">${t.compatibilityTitle}</h2><p class="muted">${t.compatibilityIntro}</p><div class="compatibility-scroll" role="region" aria-labelledby="compatibility-heading" tabindex="0"><table class="compatibility-table"><caption>${esc(e.name)} — ${t.compatibilityTitle}</caption><thead><tr>${[t.compatibilityGame,t.compatibilityVersion,t.compatibilityStatus,t.compatibilityNotes].map(label=>`<th scope="col">${label}</th>`).join('')}</tr></thead><tbody>${bananaCompatibility.rows.map(row=>{const game=games.find(g=>g.id===row.game);return `<tr><th scope="row"><a href="${href(l,`games/${game.id}`)}">${esc(game.name)}</a><code>${row.titleId}</code></th><td>${esc(row.version)}</td><td>${esc(compatibilityStatus(row,t))}</td><td>${esc(row.notes[l])}</td></tr>`;}).join('')}</tbody></table></div><div class="setup-sources"><p>${t.citations} · ${t.setupReviewed} <time datetime="${bananaCompatibility.reviewed}">${bananaCompatibility.reviewed}</time></p><ul>${bananaCompatibility.sources.map(source=>`<li>${external(source.url,esc(source.label))}</li>`).join('')}</ul></div></section>`;
}
function releaseList(e,l) {const t=releaseCopyFor(e,copy[l]),data=cache[e.id]; return `<section id="downloads" class="downloads"><p class="eyebrow">${t.downloads}</p><h2>${t.releases}</h2><p class="muted">${t.releaseIntro}</p>${e.downloadNote?`<p class="inline-note">${esc(e.downloadNote[l])}</p>`:''}${e.downloadLinks?`<ul class="asset-list">${e.downloadLinks.map(link=>`<li>${external(link.url,esc(link.name))}</li>`).join('')}</ul>`:''}<p class="fineprint" data-release-snapshot="${e.id}">${renderReleaseSnapshot(data,t)}</p><div class="release-list" data-release-list="${e.id}">${renderReleaseList(data,t,{showAssets:e.releaseAssets!==false,showLinks:e.releaseLinks!==false})}</div></section>`;}
function emulatorPage(e,l) {const t=copy[l]; return `${breadcrumb(l,'emulators',e.name)}<section class="detail-hero"><div>${emuIcon(e)}<p class="eyebrow">${e.label[l]} / ${esc(e.owner)}</p><h1>${e.name}</h1><p class="detail-lede">${e.summary[l]}</p><div class="card-release detail-release" data-release-id="${e.id}" ${latestRelease(cache[e.id]) || cache[e.id]?.fetchedAt ? '' : 'hidden'}>${renderLatestRelease(cache[e.id], t)}</div><div class="hero-actions"><a class="button primary" href="#downloads">${icon('download')}${t.downloads}</a><a class="button secondary" href="#getting-started">${t.guide}</a>${external(e.repo,t.sourceLink,'button secondary')}</div></div><aside class="fact-card"><p class="eyebrow">${t.quickFacts}</p><dl><div><dt>${t.maintainer}</dt><dd>${esc(e.owner)}</dd></div><div><dt>${t.platforms}</dt><dd>${e.platforms.join(' / ')}</dd></div><div><dt>${t.status}</dt><dd><span class="live-dot ${e.statusKey}"></span>${e.status[l]}<span class="status-activity" data-commit-id="${e.id}">${renderLatestCommit(cache[e.id],t,e)}</span></dd></div>${e.alias?`<div><dt>${t.alias}</dt><dd>${esc(e.alias)}</dd></div>`:''}</dl><p class="fineprint">${t.platformNote}</p></aside></section><div class="detail-columns"><div><section class="prose"><p class="eyebrow">${t.overview}</p><h2>${e.label[l]}</h2><p>${e.detail[l]}</p><aside class="inline-note">${e.note[l]}</aside></section>${compatibilitySection(e,l)}${gettingStartedSection(e,l)}${releaseList(e,l)}</div><aside class="detail-sidebar"><p class="eyebrow">${t.relatedGames}</p>${e.games.length?e.games.map(id=>{const g=games.find(x=>x.id===id);return `<a class="mini-game" href="${href(l,`games/${id}`)}"><div>${art(g)}</div><span>${esc(g.name)} <span aria-hidden="true">↗</span></span></a>`;}).join(''):`<p class="muted">${t.noRelated}</p>`}<a class="text-link" href="${href(l,'guide')}">${t.guide} ↗</a><a class="text-link" href="${href(l,'about')}">${t.about} ↗</a></aside></div>${citations(l,[e.repo,`${e.repo}/commits`,...(emulatorIcons[e.id]?[emulatorIcons[e.id].source]:[]),...(e.originalRepo?[e.originalRepo]:[]),...(e.extraSource?[e.extraSource]:[])],e.reviewed||reviewed)}<section class="related-section" data-nosnippet><h2>${t.relatedProjects}</h2><div class="emu-grid">${emulators.filter(x=>x.id!==e.id).slice(0,3).map(x=>emuCard(x,l)).join('')}</div></section>`;}
function gamePage(g,l) {const t=copy[l]; const es=g.recommendations.map(id=>emulators.find(e=>e.id===id)); return `${breadcrumb(l,'games',g.name)}<section class="detail-hero game-detail-hero"><div><span class="evidence ${g.evidence}">${t[g.evidence]}</span><h1>${esc(g.name)}</h1><p class="detail-lede">${g.summary[l]}</p>${external(g.source,t.officialGame,'text-link')}</div><div class="detail-art">${art(g,true)}</div></section><div class="detail-columns"><div><section class="prose"><p class="eyebrow">${t.evidence}</p><h2>${t.recommended}</h2><p>${g.reason[l]}</p>${g.recommendations.includes('banana-native')?bananaGameNote(g,l):''}<aside class="inline-note">${t.evidenceNote}</aside></section><div class="recommendation-list">${es.map(e=>`<article class="recommendation">${emuIcon(e)}<div><h3><a href="${href(l,`emulators/${e.id}`)}">${e.name} ↗</a></h3><p>${e.summary[l]}</p>${e.id==='banana-native'?bananaGameNote(g,l):reportedGameNote(e,g,l)}<div class="platforms">${e.platforms.map(p=>`<span>${p}</span>`).join('')}</div></div><a class="button secondary" href="${href(l,`emulators/${e.id}`)}">${t.details}${icon('arrow')}</a></article>`).join('')}</div>${tools.some(e=>e.game===g.id)?toolSection(l,false,tools.filter(e=>e.game===g.id)):''}</div><aside class="fact-card"><p class="eyebrow">${t.facts}</p><dl><div><dt>${t.platform}</dt><dd>Nintendo Switch 2</dd></div><div><dt>${t.year}</dt><dd>${g.year}</dd></div><div><dt>${t.genre}</dt><dd>${genres[g.genre][l]}</dd></div><div><dt>${t.updated}</dt><dd>${gameReviewed(g)}</dd></div></dl><p class="fineprint">${t.noGameDownload}</p></aside></div>${citations(l,[g.source,...(g.evidenceSource?[g.evidenceSource]:[]),...(g.evidenceSources||[]),...(g.recommendations.includes('banana-native')?bananaCompatibility.sources.map(source=>source.url):[]),...tools.filter(e=>e.game===g.id).flatMap(e=>e.sources),...es.flatMap(e=>[e.repo,...(e.extraSource?[e.extraSource]:[])])],gameReviewed(g))}<section class="related-section"><h2>${t.games}</h2><div class="game-grid">${games.filter(x=>x.id!==g.id).slice(0,3).map(x=>gameCard(x,l)).join('')}</div></section>`; }
function articlePage(type,l) {const t=copy[l],isGuide=type==='guide'; return `${breadcrumb(l,type)}<header class="article-heading"><p class="eyebrow">SWITCH2E / ${t[type]}</p><h1>${isGuide?t.guideHeading:t.aboutHeading}</h1><p class="detail-lede">${isGuide?t.guideIntro:t.aboutIntro}</p></header><div class="editorial-grid">${[1,2,3,4].map(n=>`<section class="editorial-card"><span class="step-number">0${n}</span><h2>${t[`${isGuide?'step':'methodology'}${n}`]}</h2><p>${t[`${isGuide?'step':'methodology'}${n}Text`]}</p></section>`).join('')}</div>${isGuide?`<div class="hero-actions"><a class="button primary" href="${href(l,'games')}">${t.browse}${icon('arrow')}</a><a class="button secondary" href="${href(l,'about')}">${t.about}</a></div>`:citations(l,emulators.map(e=>e.repo))}${faq(l)}`;}
function legalPage(type, language) {
  const text = legalCopy[language];
  const sections = text[`${type}Sections`];
  const related = type === 'terms' ? 'privacy' : 'terms';
  return `${breadcrumb(language, type)}
    <header class="article-heading legal-heading">
      <p class="eyebrow">SWITCH2E / LEGAL</p><h1>${esc(text[type])}</h1>
      <p class="detail-lede">${esc(text[`${type}Intro`])}</p>
      <p class="legal-updated">${esc(text.effective)}: <time datetime="${legalUpdated}">${legalUpdated}</time></p>
    </header>
    <div class="legal-layout">
      <nav class="legal-contents" aria-label="${esc(text.contents)}">
        <h2>${esc(text.contents)}</h2>
        <ol>${sections.map(([title], index) => `<li><a href="#legal-${index + 1}">${esc(title)}</a></li>`).join('')}</ol>
      </nav>
      <article class="legal-document" aria-label="${esc(text[type])}">
        ${sections.map(([title, paragraphs], index) => `<section id="legal-${index + 1}" aria-labelledby="legal-heading-${index + 1}">
          <h2 id="legal-heading-${index + 1}">${index + 1}. ${esc(title)}</h2>
          ${paragraphs.map(paragraph => `<p>${esc(paragraph)}</p>`).join('')}
        </section>`).join('')}
        <section class="legal-contact" aria-labelledby="legal-contact-title"><h2 id="legal-contact-title">${esc(text.contact)}</h2>
          <p>Switch2e · Telegram ${external(legalContact.url, esc(legalContact.name))}</p>
          <p>${esc(text.related)}: <a href="${href(language, related)}">${esc(text[related])}</a></p>
        </section>
        ${type === 'privacy' ? `<section class="legal-references" aria-labelledby="legal-references-title">
          <h2 id="legal-references-title">${esc(text.references)}</h2>
          <ul>${privacyReferences.map(reference => `<li>${external(reference.url, esc(reference.label))}</li>`).join('')}</ul>
        </section>` : ''}
      </article>
    </div>`;
}
const emulatorDirectoryReviewed = [...emulators.map(e=>e.reviewed||reviewed),toolsReviewed].sort().at(-1);
const gameReviewed = game => [...game.recommendations.map(id=>emulators.find(e=>e.id===id)?.reviewed||reviewed),...(tools.filter(e=>e.game===game.id).map(e=>e.reviewed))].sort().at(-1);
const routeReviewed = route => ['terms','privacy'].includes(route.type) ? legalUpdated : route.type==='advertise' ? advertisingUpdated : route.type==='tool' ? route.entry.reviewed : ['home','emulators','games'].includes(route.type) ? emulatorDirectoryReviewed : route.type==='game' ? gameReviewed(route.entry) : ['tools','guide','about'].includes(route.type) ? toolsReviewed : route.type==='platform' ? platformsReviewed : route.type==='emulator' ? (route.entry.reviewed||gettingStarted[route.entry.id].reviewed||gettingStartedReviewed) : reviewed;
const routes=[{path:'tools',type:'tools'},...tools.map(entry=>({path:`tools/${entry.id}`,type:'tool',entry})),{path:'',type:'home'}, {path:'emulators',type:'emulators'}, {path:'games',type:'games'}, {path:'guide',type:'guide'}, {path:'about',type:'about'}, {path:'advertise',type:'advertise'}, {path:'terms',type:'terms'}, {path:'privacy',type:'privacy'}, ...platforms.map(entry=>({path:`platforms/${entry.id}`,type:'platform',entry})), ...emulators.map(e=>({path:`emulators/${e.id}`,type:'emulator',entry:e})),...games.map(g=>({path:`games/${g.id}`,type:'game',entry:g}))];
function schema(route,l,title,description){const t=copy[l],url=absolute(href(l,route.path)),pageId=`${url}#webpage`; const org={ '@type':'Organization','@id':`${siteURL}/#organization`,name:'Switch2e',url:siteURL,logo:absolute('/assets/favicon.svg')}; const graph=[org,{'@type':'WebSite','@id':`${siteURL}/#website`,name:'Switch2e',url:siteURL,inLanguage:languages,publisher:{'@id':org['@id']}},{'@type':['home','emulators','games','platform','tools'].includes(route.type)?'CollectionPage':route.type==='about'?'AboutPage':'WebPage','@id':pageId,url,name:title,description,inLanguage:l,isPartOf:{'@id':`${siteURL}/#website`},dateModified:routeReviewed(route),publisher:{'@id':org['@id']}}];
 if(route.path) {const crumbs=[{'@type':'ListItem',position:1,name:t.home,item:absolute(href(l))}];const parent=['emulator','platform'].includes(route.type)?'emulators':route.type==='game'?'games':route.type==='tool'?'tools':null;if(parent)crumbs.push({'@type':'ListItem',position:2,name:parent==='tools'?toolCopy.label[l]:t[parent],item:absolute(href(l,parent))});crumbs.push({'@type':'ListItem',position:crumbs.length+1,name:route.entry?.name||(route.type==='tools'?toolCopy.label[l]:t[route.type]),item:url});graph.push({'@type':'BreadcrumbList',itemListElement:crumbs});}
 if(['home','emulators','games','platform','tools'].includes(route.type)){const entries=route.type==='tools'?tools:route.type==='home'?[...emulators,...tools]:route.type==='games'?games:route.type==='platform'?emulators.filter(e=>e.platforms.includes(route.entry.name)):emulators;graph.push({'@type':'ItemList','@id':`${url}#directory`,numberOfItems:entries.length,itemListElement:entries.map((e,i)=>({'@type':'ListItem',position:i+1,name:e.name,url:absolute(href(l,`${route.type==='games'?'games':e.kind==='static-recompilation'?'tools':'emulators'}/${e.id}`))}))});}
 if(route.type==='emulator'){const e=route.entry;graph.push({'@type':'SoftwareApplication','@id':`${url}#software`,name:e.name,alternateName:e.alias,citation:gettingStarted[e.id].sources.map(source=>source.url),...(emulatorIcons[e.id]?{image:absolute(emulatorIcons[e.id].file)}:{}),applicationCategory:'GameApplication',applicationSubCategory:'Console emulator',...(e.maintenance?{creativeWorkStatus:e.maintenance}:{}),operatingSystem:e.platforms.join(', '),description:e.summary[l],url:e.repo,downloadUrl:`${e.repo}/releases`,author:{'@type':'Person',name:e.owner},isAccessibleForFree:true,mainEntityOfPage:{'@id':pageId}});}
 if(route.type==='tool'){const e=route.entry;graph.push({'@type':'SoftwareApplication','@id':`${url}#software`,name:e.name,applicationCategory:'GameApplication',applicationSubCategory:'Static recompilation tools and runtime',operatingSystem:e.platforms.join(', '),description:e.summary[l],url,sameAs:e.repo,...(e.downloadURL?{downloadUrl:e.downloadURL}:e.releaseLinks===false?{}:{downloadUrl:`${e.repo}/releases`}),...(e.maintenance?{creativeWorkStatus:e.maintenance}:{}),...(e.predecessor?{isBasedOn:absolute(href(l,`tools/${e.predecessor}`))}:{}),license:e.licenseURL,author:{'@type':'Person',name:e.owner},isAccessibleForFree:true,citation:e.sources,mainEntityOfPage:{'@id':pageId}},{'@type':'FAQPage',inLanguage:l,mainEntity:e.faqs.map(item=>({'@type':'Question',name:item.question[l],acceptedAnswer:{'@type':'Answer',text:item.answer[l]}}))});}
 if(route.type==='game'){const g=route.entry;graph.push({'@type':'VideoGame','@id':`${url}#game`,name:g.name,description:g.summary[l],gamePlatform:'Nintendo Switch 2',genre:genres[g.genre][l],sameAs:g.source,...(media[g.id]?{image:absolute(`/assets/games/${g.id}.webp`)}:{}),mainEntityOfPage:{'@id':pageId}});}
 if(['home','guide','about'].includes(route.type))graph.push({'@type':'FAQPage',inLanguage:l,mainEntity:t.faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});
 return {'@context':'https://schema.org','@graph':graph}; }
function layout(route,l,content,title,description,{noindex=false}={}){const t=copy[l],url=absolute(href(l,route.path)),isE=route.type.startsWith('emulator'),isG=route.type.startsWith('game');const image=route.type==='game'&&media[route.entry.id]?absolute(`/assets/games/${route.entry.id}.webp`):absolute('/assets/og-card.png');const searchData=[...tools.map(e=>({name:e.name,sub:e.summary[l],text:`${e.name} ${e.owner} ${games.find(g=>g.id===e.game).name} 静态转译 重编译 recompilation 再コンパイル`,url:href(l,`tools/${e.id}`),type:toolCopy.label[l]})),...platforms.map(p=>({name:p.title[l],sub:p.name,text:`${p.name} ${p.title[l]} ${p.description[l]}`,url:href(l,`platforms/${p.id}`),type:t.emulators})),...emulators.map(e=>({name:e.name,sub:e.owner,text:`${e.name} ${e.alias||''} ${e.owner}`,url:href(l,`emulators/${e.id}`),type:t.emulators})),...games.map(g=>({name:g.name,sub:genres[g.genre][l],text:`${g.name} ${g.summary[l]}`,url:href(l,`games/${g.id}`),type:t.games}))];const localePrompt=l==='en'&&route.type==='home'?`<aside class="locale-prompt" data-locale-prompt hidden aria-label="语言提示"><p>检测到中文浏览器，是否切换到中文？</p><a class="button primary" href="/zh-CN/" lang="zh-CN">切换到简体中文 <span aria-hidden="true">↗</span></a><button type="button" data-dismiss-locale-prompt aria-label="关闭语言提示">继续使用英文 <span aria-hidden="true">×</span></button></aside>`:'';return `<!doctype html><html lang="${l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${noindex?'noindex, follow':'index, follow, max-image-preview:large, max-snippet:-1'}"><meta name="theme-color" content="#f7f8f2"><link rel="canonical" href="${url}">${languages.map(lang=>`<link rel="alternate" hreflang="${lang}" href="${absolute(href(lang,route.path))}">`).join('')}<link rel="alternate" hreflang="x-default" href="${absolute(href('en',route.path))}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><meta property="og:site_name" content="Switch2e"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:locale" content="${t.locale}">${languages.filter(x=>x!==l).map(x=>`<meta property="og:locale:alternate" content="${copy[x].locale}">`).join('')}<meta property="og:image" content="${image}"><meta property="og:image:alt" content="${esc(route.entry?.name||'Switch2e — A new world. More ways to play.')}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${image}"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${json(schema(route,l,title,description))}</script><script type="module" src="/assets/app.js"></script></head><body id="top" data-locale="${l}"><a class="skip-link" href="#main">${l==='en'?'Skip to content':l==='ja'?'本文へ':'跳至主要内容'}</a>${staticNotice(l)}<header class="site-header"><div class="header-inner"><a class="brand" href="${href(l)}" aria-label="switch2e.com ${t.home}">${mark}<span>switch<span class="brand-2">2</span>e<span class="brand-domain"><span class="brand-dot">.</span>com</span></span></a><nav class="main-nav" aria-label="${t.directory}" id="main-nav"><a class="${isE?'current':''}" href="${href(l,'emulators')}">${t.emulators}</a><a class="${isG?'current':''}" href="${href(l,'games')}">${t.games}</a><a class="${['tool','tools'].includes(route.type)?'current':''}" href="${href(l,'tools')}">${toolCopy.label[l]}</a><a class="${route.type==='guide'?'current':''}" href="${href(l,'guide')}">${t.guide}<span class="nav-arrow" aria-hidden="true">↗</span></a></nav><div class="header-tools"><button class="search-trigger" data-open-search aria-label="${t.searchLabel}">${icon('search')}<span>${l==='en'?'Search':l==='ja'?'検索':'搜索'}</span><kbd>⌘ K</kbd></button><div class="language-picker"><button class="language-trigger" aria-expanded="false" aria-controls="language-menu"><span aria-hidden="true">◎</span>${l==='en'?'EN':l==='ja'?'JA':'中文'}<span aria-hidden="true">⌄</span></button><div id="language-menu" class="language-menu" hidden>${languages.map(lang=>`<a href="${href(lang,route.path)}" lang="${lang}" hreflang="${lang}" ${lang===l?'aria-current="true"':''}>${languageNames[lang]}${lang===l?' ✓':''}</a>`).join('')}</div></div><button class="menu-toggle" aria-label="${t.menu}" aria-controls="main-nav" aria-expanded="false"><span></span><span></span></button></div></div></header>${localePrompt}<main id="main" class="container">${content}</main><footer class="site-footer"><div class="container"><div class="footer-main"><div><a class="brand" href="${href(l)}">${mark}<span>switch<span class="brand-2">2</span>e<span class="brand-domain"><span class="brand-dot">.</span>com</span></span></a><p>${t.footerText}</p><p class="footer-support">${t.supportEmail}: <a href="mailto:support@switch2e.com">support@switch2e.com</a></p><span class="footer-tag">INDEPENDENT BY DESIGN ↗</span></div><div><h2>${t.directory}</h2><a href="${href(l,'emulators')}">${t.emulators}</a><a href="${href(l,'games')}">${t.games}</a><a href="${href(l,'tools')}">${toolCopy.label[l]}</a>${platforms.map(p=>`<a href="${href(l,`platforms/${p.id}`)}">${p.name}</a>`).join('')}</div><div><h2>${t.resources}</h2><a href="${href(l,'guide')}">${t.guide}</a><a href="${href(l,'about')}">${t.about}</a><a href="${href(l,'advertise')}" ${route.type==='advertise'?'aria-current="page"':''}>${t.advertise}</a><a href="${href(l,'terms')}" ${route.type==='terms'?'aria-current="page"':''}>${t.terms}</a><a href="${href(l,'privacy')}" ${route.type==='privacy'?'aria-current="page"':''}>${t.privacy}</a><a href="/llms.txt">llms.txt ↗</a></div><div><h2>LANGUAGE</h2>${languages.map(lang=>`<a href="${href(lang,route.path)}" lang="${lang}" hreflang="${lang}">${languageNames[lang]}</a>`).join('')}</div></div><div class="footer-bottom"><div><p>${t.footerNote}</p><p>${t.footerLegal}</p></div><span>© 2026 <a class="footer-domain" href="${siteURL}">switch2e.com</a></span><a href="#top">${t.backTop} ↑</a></div></div></footer><dialog class="search-dialog" aria-label="${t.searchLabel}"><form method="dialog"><div class="search-input-row">${icon('search')}<input id="global-search" type="search" placeholder="${t.search}" aria-label="${t.searchLabel}" autocomplete="off"><button class="close-search" aria-label="${t.close}">Esc</button></div></form><p class="search-hint">${t.searchHint}</p><div class="search-results" aria-live="polite"></div><p class="search-no-results" hidden>${t.searchEmpty}</p></dialog><script type="application/json" id="search-data">${json(searchData)}</script></body></html>`;}
const pages=[];
for(const l of languages)for(const route of routes){const t=copy[l];let content,title,description;switch(route.type){case 'terms':case 'privacy':content=legalPage(route.type,l);title=`${legalCopy[l][`${route.type}Title`]} | Switch2e`;description=legalCopy[l][`${route.type}Description`];break;case 'advertise':content=advertisingPage(l);title=`${advertisingCopy[l].pageTitle} | Switch2e`;description=advertisingCopy[l].description;break;case 'tool':content=toolPage(route.entry,l);title=`${route.entry.seoTitle[l]} | Switch2e`;description=route.entry.seoDescription?.[l]||route.entry.summary[l];break;case 'tools':content=`${breadcrumb(l,'tools')}<header class="listing-heading"><p class="eyebrow">SWITCH2E / STATIC RECOMPILATION</p><h1>${toolCopy.heading[l]}</h1><p class="detail-lede">${toolCopy.intro[l]}</p></header>${toolGrid(tools,l)}`;title=`${toolCopy.heading[l]} | Switch2e`;description=toolCopy.intro[l];break;case 'platform':content=platformPage(route.entry,l);title=`${route.entry.title[l]} | Switch2e`;description=route.entry.description[l];break;case 'home': content=home(l);title=l==='en'?'Switch2e — Switch 2 Emulators, Recompilation Tools & Games':l==='ja'?'Switch2e — Switch 2 エミュレーター・再コンパイル・ゲーム':'Switch2e — Switch 2 模拟器、游戏转译工具与推荐';description=l==='en'?'Explore Switch 2 emulators and Recompia for Pokémon Pokopia, EmblemWeave, Longshot and NX2navi recompilation tools, with downloads and setup guides.':l==='ja'?'Switch 2 エミュレーター、Pokémon Pokopia 向け Recompia、EmblemWeave・Longshot・NX2navi の再コンパイルを紹介。動作要件・導入・配布元を確認。':'探索 Switch 2 模拟器、Pokémon Pokopia 转译工具 Recompia，以及 EmblemWeave、Longshot、NX2navi，查看游戏推荐、系统要求、安装指南与原始下载。';break;case 'emulators': case 'games':content=`${breadcrumb(l,route.type)}<header class="listing-heading"><p class="eyebrow">SWITCH2E / ${t.directory}</p><h1>${route.type==='emulators'?t.emuHeading:t.gameHeading}</h1><p class="detail-lede">${route.type==='emulators'?t.emuIntro:t.gameIntro}</p></header>${route.type==='emulators'?emuSection(l,true):gameSection(l,true)}${cta(l)}`;title=`${t[route.type]} — Switch 2 | Switch2e`;description=route.type==='emulators'?`${t.emuIntro} Eglantine, Lichii, PokeDinner, Fortune’s Eden, Fritchii, Selevet Eglantine, Banana Native, Hokkaido.`:t.gameDirectoryDescription;break;case 'emulator':content=emulatorPage(route.entry,l);title=route.entry.seo?.title[l]||`${route.entry.name} — ${t.overview} & ${t.downloads} | Switch2e`;description=route.entry.seo?.description[l]||route.entry.summary[l];break;case 'game':content=gamePage(route.entry,l);title=`${route.entry.name} — ${t.games} | Switch2e`;description=route.entry.seoDescription?.[l]||`${route.entry.summary[l]} ${route.entry.reason[l]}`;break;default:content=articlePage(route.type,l);title=`${t[route.type]} — Switch 2 | Switch2e`;description=route.type==='guide'?`${t.guideIntro} ${t.step1Text}`:`${t.aboutIntro} ${t.methodology1Text}`;}
description=clipDescription(description,l);
const html=layout(route,l,content,title,description);const relativeDir=l==='en'?route.path:`${l}/${route.path}`;const file=resolve(out,relativeDir||'.','index.html');await mkdir(dirname(file),{recursive:true});await writeFile(file,html);pages.push({url:absolute(href(l,route.path)),path:route.path,l,modified:routeReviewed(route)});}
const nf={path:'',type:'notFound'};await writeFile(resolve(out,'404.html'),layout(nf,'en',`<section class="not-found"><p class="eyebrow">404 / OFF THE MAP</p><h1>${copy.en.notFound}</h1><p>${copy.en.notFoundText}</p><a class="button primary" href="/">${copy.en.backHome}${icon('arrow')}</a></section>`,'Page not found | Switch2e',copy.en.notFoundText,{noindex:true}).replace(/<link rel="(?:canonical|alternate)"[^>]*>/g,''));
await writeFile(resolve(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${pages.map(p=>`<url><loc>${p.url}</loc><lastmod>${p.modified}</lastmod>${[...languages,'x-default'].map(l=>`<xhtml:link rel="alternate" hreflang="${l}" href="${absolute(href(l==='x-default'?'en':l,p.path))}"/>`).join('')}</url>`).join('')}</urlset>`);
await writeFile(resolve(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${siteURL}/sitemap.xml\n`);
const oldEnglishRoutes = routes.flatMap(route => {
  const oldPath = route.path ? `/en/${route.path}/` : '/en/';
  const target = href('en', route.path);
  return [`${oldPath} ${target} 301`, `${oldPath.slice(0, -1)} ${target} 301`];
});
await writeFile(resolve(out,'_redirects'),[...new Set(oldEnglishRoutes)].join('\n') + '\n');
const llms=`# Switch2e\n\n> Independent, source-linked directory of experimental Nintendo Switch 2 emulators, game-specific forks and static recompilation tools.\n\n## Editorial context\n- Not affiliated with Nintendo or listed projects. No games, keys or firmware are hosted.\n- Emulator editorial baseline reviewed on ${reviewed}; recompilation tools reviewed on ${toolsReviewed}. No independent Switch2e game benchmarks.\n- Evidence levels: developer reported, project focus, and unverified research candidate. Recommendations do not guarantee playability.\n- Release metadata sync does not imply a new compatibility test.\n- Frizti/Lichii is now Frizti/Fritchii, distinct from zortos293/Lichii.\n\n## Directory\n${emulators.map(e=>`- [${e.name}](${absolute(href('en',`emulators/${e.id}`))}): ${e.summary.en} Reviewed: ${e.reviewed||reviewed}. Source: ${e.extraSource||e.repo}`).join('\n')}\n\n## Recompilation tools\n${tools.map(e=>`- [${e.name}](${absolute(href('en',`tools/${e.id}`))}): ${e.summary.en} ${e.note.en} ${e.successor?`Successor: ${absolute(href('en',`tools/${e.successor}`))}. ${e.retirement.en}`:''} Reviewed: ${e.reviewed}. Sources: ${e.sources.join(' ')}`).join('\n')}\n\n## Operating systems\n${platforms.map(p=>`- [${p.title.en}](${absolute(href('en',`platforms/${p.id}`))}): ${p.description.en}`).join('\n')}\n\n## Games\n${games.map(g=>`- [${g.name}](${absolute(href('en',`games/${g.id}`))}): ${g.reason.en} Evidence: ${g.evidence}.`).join('\n')}\n\n## Guides\n- [Getting started](${absolute(href('en','guide'))})\n- [Methodology](${absolute(href('en','about'))})\n\n## Languages\n- [English](${absolute(href('en'))})\n- [简体中文](${siteURL}/zh-CN/)\n- [日本語](${siteURL}/ja/)\n\n## Machine-readable content\n- [Directory JSON](${siteURL}/directory.json)\n- [Full text](${siteURL}/llms-full.txt)\n- [Sitemap](${siteURL}/sitemap.xml)\n`;
await writeFile(resolve(out,'llms.txt'),llms);
await writeFile(resolve(out,'llms-full.txt'),`${llms}\n${languages.map(l=>`# ${languageNames[l]}\n\n${tools.map(e=>`## ${e.name}\nURL: ${absolute(href(l,`tools/${e.id}`))}\n${e.summary[l]}\n${e.detail[l]}\n${e.note[l]}\n${e.successor?`${e.retirement[l]}\nSuccessor: ${absolute(href(l,`tools/${e.successor}`))}`:''}\n${[...e.requirements,...e.features,...e.steps].map(text=>text[l]).join('\n')}\n${(e.sections||[]).map(section=>`### ${section.title[l]}\n${(section.paragraphs||[]).map(text=>text[l]).join('\n')}\n${(section.rows||[]).map(row=>row.map(text=>text[l]).join(' | ')).join('\n')}\nSource: ${section.source}`).join('\n')}\n${e.downloadNote?`${e.downloadNote[l]}\nDownload: ${e.downloadURL}`:''}\n${e.faqs.map(item=>`${item.question[l]}: ${item.answer[l]}`).join('\n')}\nReviewed: ${e.reviewed}\nSources: ${e.sources.join(' ')}`).join('\n')}\n\n${platforms.map(p=>`## ${p.title[l]}\n${p.intro[l]}\n${p.sections.map(s=>`${s.title[l]}: ${s.text[l]}`).join('\n')}\nURL: ${absolute(href(l,`platforms/${p.id}`))}`).join('\n')}\n\n${emulators.map(e=>`## ${e.name}\n${e.summary[l]}\n${e.detail[l]}\n${e.note[l]}\n${e.compatibility?`${e.compatibility.intro[l]}\n${e.compatibility.rows.map(row=>`${games.find(game=>game.id===row.game).name}: ${row.notes[l]}`).join('\n')}\nSource: ${e.compatibility.source}\nSource: ${e.compatibility.releaseSource}`:''}\n${e.successor?`${e.retirement[l]}\nSuccessor: ${absolute(href(l,`tools/${e.successor}`))}`:''}\n${e.id==='banana-native'?bananaCompatibility.rows.map(row=>{const game=games.find(g=>g.id===row.game);return `${game.name} (${row.titleId}), ${row.version}: ${compatibilityStatus(row,copy[l])}. ${row.notes[l]}`;}).join('\n'):''}\nSource: ${e.repo}\n### ${copy[l].guide}\n${gettingStarted[e.id].note[l]}\n${gettingStarted[e.id].steps.map((step,i)=>`${i+1}. ${step.title[l]}: ${step.text[l]}`).join('\n')}\nSetup reviewed: ${gettingStarted[e.id].reviewed||gettingStartedReviewed}\n${gettingStarted[e.id].sources.map(source=>`Source: ${source.url}`).join('\n')}\n`).join('\n')}\n${games.map(g=>`## ${g.name}\n${g.reason[l]}\n${g.recommendations.includes('banana-native')?`Banana Native (Android): ${bananaCompatibility.rows.find(row=>row.game===g.id).notes[l]}`:''}\nEvidence: ${g.evidence}\nSource: ${g.source}\n`).join('\n')}`).join('\n')}`);
await writeFile(resolve(out,'directory.json'),JSON.stringify({name:'Switch2e',siteURL,sourceReviewed:reviewed,toolsReviewed,languages,tools:tools.map(({api,...e})=>({...e,url:absolute(href('en',`tools/${e.id}`)),downloadURL:e.downloadURL||(e.releaseLinks===false?null:`${e.repo}/releases`),...(e.successor?{successorURL:absolute(href('en',`tools/${e.successor}`))}:{})})),platforms:platforms.map(p=>({...p,url:absolute(href('en',`platforms/${p.id}`)),emulators:emulators.filter(e=>e.platforms.includes(p.name)).map(e=>e.id)})),evidencePolicy:'Developer claims and project focus are not independent benchmarks. Unverified entries are research candidates only.',emulators:emulators.map(({api,...e})=>({...e,...(emulatorIcons[e.id]?{icon:emulatorIcons[e.id]}:{}),...(e.id==='banana-native'?{compatibility:bananaCompatibility}:{}),gettingStarted:{reviewed:gettingStarted[e.id].reviewed||gettingStartedReviewed,...gettingStarted[e.id]},url:absolute(href('en',`emulators/${e.id}`)),downloadURL:`${e.repo}/releases`})),games},null,2));
await writeFile(resolve(out,'_headers'),`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; frame-src 'none'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'\n`);
